<?php get_header(); ?><main class="cm-content-wrap"><div class="cm-post-grid"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="cm-card"><div class="cm-meta"><?php echo esc_html(get_post_type()); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(cm_excerpt_text(get_post())); ?></p></article><?php endwhile;else: ?><h1>لا توجد نتائج</h1><?php endif; ?></div></main><?php get_footer(); ?>
